// === Tab: mySketch.js ===
/*
  粒子流莫比乌斯环
  粒子沿环的参数方程运动，新粒子不断从起点喷出，形成动态流动效果
  鼠标按下时切换CRT复古滤镜
*/

let radius =220;        // 环的主半径
let widthBand = 50;      // 环的宽度
let particles = [];
let flowSpeed = 0.009;   // 粒子沿环移动的速度
let spawnRate = 2;       // 每帧生成的新粒子数量
let maxParticles = 1000;

let crtShader;
let useCRT = false;      // 改用鼠标按下时触发，每帧判断

// CRT着色器（不变）
const crtShaderSrc = `
precision highp float;
uniform sampler2D tex0;
varying vec2 vTexCoord;

vec2 curveRemapUV(vec2 uv) {
  uv = 2.0 * uv - 1.0;
  vec2 curvature = vec2(16.0);
  vec2 offset = abs(uv.yx) / curvature;
  uv = uv + uv * offset * offset;
  uv = uv * 0.5 + 0.5;
  return uv;
}

vec4 adjBrightness(vec2 inUV, vec4 clr) {
  float r = 0.5;
  vec2 cornerUV = min(2.0 * (0.5 - abs(inUV - vec2(0.5))) + r, 1.0);
  float br = pow(cornerUV.x * cornerUV.y, 2.2) + 0.45;
  br = clamp(br * br * br * br + 0.55, 0.0, 1.0);
  return clr * br;
}

void main() {
  vec2 remappedUV = curveRemapUV(vTexCoord);
  vec4 baseColor = texture2D(tex0, remappedUV);
  if (remappedUV.x < 0.0 || remappedUV.y < 0.0 || remappedUV.x > 1.0 || remappedUV.y > 1.0){
    gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
  } else {
    gl_FragColor = adjBrightness(vTexCoord, baseColor);
  }
  gl_FragColor *= abs(sin(remappedUV.y * 576.0));
  float lum = dot(gl_FragColor.rgb, vec3(0.299, 0.587, 0.114));
  vec3 greenPhosphor = vec3(0.2, 1.0, 0.3);
  gl_FragColor.rgb = lum * greenPhosphor;
  gl_FragColor.a = 1.0;
}
`;

class Particle {
  constructor(phi, t, speed) {
    this.phi = phi;           // 环向角度 0~2PI
    this.t = t;              // 宽度方向 -1~1
    this.speed = speed;      // 移动速度
    this.age = 0;
    this.lifespan = TWO_PI / speed;  // 走完一圈所需帧数
  }

  // 根据当前phi和t计算3D坐标
  updatePosition() {
    let halfPhi = this.phi / 2;
    let cosHalf = cos(halfPhi);
    let sinHalf = sin(halfPhi);
    let r = radius + this.t * widthBand * cosHalf;
    this.x = r * cos(this.phi);
    this.y = r * sin(this.phi);
    this.z = this.t * widthBand * sinHalf;
  }

  update() {
    this.phi += this.speed;
    this.age++;
    this.updatePosition();
    return this.phi < TWO_PI; // 返回false表示生命周期结束
  }

  display() {
    push();
    translate(this.x, this.y, this.z);
    // 每个小粒子立方体自转，增加动感
    rotateX(frameCount * 0.2);
    rotateY(frameCount * 0.1);
    rotateZ(frameCount * 0.1);

    // 颜色随phi和t变化，体现流动感
    let hue = (degrees(this.phi) + degrees(this.t * PI)) % 360;
    let sat = map(abs(this.t), 0, 1, 60, 100);
    let bri = map(sin(this.phi), -1, 1, 70, 100);
    fill(hue, sat, bri);
    box(4);
    pop();
  }
}

function setup() {
  createCanvas(600, 600, WEBGL);
  noStroke();
  colorMode(HSB, 360, 100, 100);
  crtShader = createFilterShader(crtShaderSrc);
  pixelDensity(1);

  // 初始生成一些粒子，随机分布在环上，制造初始流动感
  for (let i = 0; i < 200; i++) {
    let phi = random(TWO_PI);
    let t = random(-1, 1);
    let p = new Particle(phi, t, flowSpeed);
    p.updatePosition();
    particles.push(p);
  }
}

function draw() {
  background(10);

  // 整体场景缓慢旋转
  rotateY(frameCount * 0.005);
  rotateX(frameCount * 0.003);

  // 生成新粒子（喷出效果）
  for (let i = 0; i < spawnRate; i++) {
    if (particles.length < maxParticles) {
      // 新粒子从 phi=0 附近开始，t 随机分布，体现从一点喷出后扩散到整个环面
      var phi = random(-0.2, 0.2);   // 起点集中在起始角
      var t = random(-1, 1);
      var p = new Particle(phi, t, flowSpeed);
      p.updatePosition();
      particles.push(p);
    }
  }

  // 更新并绘制所有粒子，移除生命周期结束的
  for (let i = particles.length - 1; i >= 0; i--) {
    var p = particles[i];
    let alive = p.update();
    p.display();
    if (!alive) {
      particles.splice(i, 1);
    }
  }

  // 鼠标按下时应用CRT滤镜
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    filter(crtShader);
  }

  // 显示粒子数量（可选，调试用）
  // fill(0, 0, 100);
  // text(`particles: ${particles.length}`, -width/2 + 50, -height/2 + 30);
}

